def holdout_guard(study):
    used = {"held": None}                 # the held-out dates, once they have been used

    def guarded(bars, held_out=False):
        if held_out:
            if used["held"] is not None:
                raise RuntimeError("the held-out data has already been used")
            used["held"] = bars.index
        elif used["held"] is not None and len(bars.index.intersection(used["held"])):
            raise RuntimeError("research data overlaps the held-out data")
        return study(bars)

    return guarded

